css:
.archdio-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #f4ecdc 0%, #e9dec5 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2b1d1a;
}
.archdio-sim-header {
    background: linear-gradient(135deg, #4a1d1f 0%, #6e2a2e 60%, #8a3236 100%);
    color: #f6e7c1;
    border-radius: 14px;
    padding: 28px 32px;
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 22px;
    box-shadow: 0 12px 32px rgba(74,29,31,0.28);
    border-bottom: 4px solid #c9a85b;
}
.archdio-sim-header-mark {
    font-size: 2.6rem;
    width: 68px;
    height: 68px;
    border-radius: 50%;
    background: rgba(246,231,193,0.12);
    border: 2px solid #c9a85b;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}
.archdio-sim-header-text { flex: 1; }
.archdio-sim-header-text h1 {
    margin: 0 0 6px 0;
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: #f6e7c1;
}
.archdio-sim-subtitle {
    color: #e6c891;
    font-size: 0.95rem;
    font-style: italic;
    letter-spacing: 0.01em;
}
.archdio-sim-period-counter {
    background: rgba(246,231,193,0.14);
    border: 1px solid #c9a85b;
    border-radius: 999px;
    padding: 10px 22px;
    color: #f6e7c1;
    font-weight: 600;
    letter-spacing: 0.05em;
    font-size: 0.9rem;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
}
.archdio-sim-period-num {
    color: #c9a85b;
    font-size: 1.1rem;
    font-weight: 800;
}
.archdio-sim-briefing {
    background: #fdf7e9;
    border-left: 5px solid #c9a85b;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 24px;
    color: #2b1d1a;
    font-size: 1rem;
    line-height: 1.6;
    box-shadow: 0 4px 14px rgba(74,29,31,0.06);
}
.archdio-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.archdio-sim-kpi-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 20px;
    border-top: 4px solid #6e2a2e;
    box-shadow: 0 6px 18px rgba(74,29,31,0.08);
    position: relative;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.archdio-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(74,29,31,0.14);
}
.archdio-kpi-corpus { border-top-color: #4a1d1f; }
.archdio-kpi-cov    { border-top-color: #c9a85b; }
.archdio-kpi-gap    { border-top-color: #8a3236; }
.archdio-kpi-score  { border-top-color: #1f6047; }
.archdio-sim-kpi-icon {
    position: absolute;
    top: 16px;
    right: 18px;
    font-size: 1.4rem;
    color: #c9a85b;
    opacity: 0.75;
}
.archdio-sim-kpi-label {
    color: #6b4a3a;
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.archdio-sim-kpi-value {
    font-size: 2rem;
    font-weight: 800;
    color: #4a1d1f;
    letter-spacing: -0.01em;
    line-height: 1.05;
}
.archdio-sim-section-title {
    font-size: 1.05rem;
    font-weight: 700;
    color: #4a1d1f;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 14px 0;
    padding-bottom: 8px;
    border-bottom: 2px solid #c9a85b;
    display: inline-block;
}
.archdio-sim-stakeholders {
    background: #fdf7e9;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(74,29,31,0.06);
}
.archdio-stakeholder-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 16px;
}
.archdio-stakeholder-card {
    background: #ffffff;
    border: 1px solid #e6d6b8;
    border-radius: 10px;
    padding: 18px;
}
.archdio-stakeholder-icon {
    font-size: 1.2rem;
    color: #c9a85b;
    margin-bottom: 6px;
}
.archdio-stakeholder-label {
    font-size: 0.85rem;
    color: #6b4a3a;
    margin-bottom: 8px;
    font-weight: 600;
}
.archdio-stakeholder-value {
    font-size: 1.6rem;
    font-weight: 800;
    color: #4a1d1f;
    margin-bottom: 8px;
}
.archdio-stakeholder-bar {
    height: 8px;
    background: #ede1c4;
    border-radius: 999px;
    overflow: hidden;
}
.archdio-stakeholder-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #6e2a2e, #c9a85b);
    transition: width 0.4s ease;
}
.archdio-sim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 26px 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(74,29,31,0.08);
    border: 1px solid #e6d6b8;
}
.archdio-round-panel {
    background: #fdf7e9;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border-left: 4px solid #c9a85b;
}
.archdio-panel-header {
    font-size: 0.95rem;
    font-weight: 700;
    color: #4a1d1f;
    letter-spacing: 0.04em;
    margin-bottom: 16px;
    text-transform: uppercase;
}
.archdio-input-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 16px;
}
.archdio-input-wide { grid-column: 1 / -1; }
.archdio-input-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #4a1d1f;
    margin-bottom: 6px;
}
.archdio-input-hint {
    font-size: 0.78rem;
    color: #6b4a3a;
    margin-top: 6px;
    font-style: italic;
    line-height: 1.4;
}
.archdio-sim-controls input[type="number"],
.archdio-sim-controls input[type="text"],
.archdio-sim-controls select {
    background: #ffffff;
    border: 1px solid #c9a85b;
    color: #2b1d1a;
    border-radius: 8px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.archdio-sim-controls input[type="number"]:focus,
.archdio-sim-controls input[type="text"]:focus,
.archdio-sim-controls select:focus {
    outline: none;
    border-color: #6e2a2e;
    box-shadow: 0 0 0 3px rgba(110,42,46,0.15);
}
.archdio-sim-controls select option {
    background: #ffffff;
    color: #2b1d1a;
}
.archdio-sim-actions {
    display: flex;
    gap: 12px;
    margin-top: 18px;
    flex-wrap: wrap;
}
.archdio-btn-submit {
    background: linear-gradient(135deg, #4a1d1f, #6e2a2e);
    color: #f6e7c1;
    border: none;
    padding: 12px 28px;
    border-radius: 8px;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.9rem;
    box-shadow: 0 4px 12px rgba(74,29,31,0.25);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.archdio-btn-submit:hover {
    background: linear-gradient(135deg, #6e2a2e, #8a3236);
    color: #f6e7c1;
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(74,29,31,0.32);
}
.archdio-btn-undo {
    border: 1px solid #c9a85b;
    color: #6b4a3a;
    background: #ffffff;
    padding: 12px 22px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.85rem;
}
.archdio-btn-undo:hover {
    background: #fdf7e9;
    color: #4a1d1f;
    border-color: #6e2a2e;
}
.archdio-sim-history-wrap {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(74,29,31,0.06);
    border: 1px solid #e6d6b8;
}
.archdio-history-table {
    width: 100%;
    margin-bottom: 0;
    color: #2b1d1a;
}
.archdio-history-table thead th {
    background: #4a1d1f;
    color: #f6e7c1;
    font-weight: 700;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border: none;
    padding: 10px 12px;
}
.archdio-history-table tbody td {
    padding: 10px 12px;
    border-top: 1px solid #ede1c4;
    font-size: 0.92rem;
}
.archdio-history-table tbody tr:nth-child(even) {
    background: #fdf7e9;
}
.archdio-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}
.archdio-chart-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 20px;
    box-shadow: 0 4px 14px rgba(74,29,31,0.06);
    border: 1px solid #e6d6b8;
}
.archdio-chart-title {
    font-size: 0.92rem;
    font-weight: 700;
    color: #4a1d1f;
    margin-bottom: 14px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #c9a85b;
    padding-bottom: 8px;
}
.archdio-chart-canvas-wrap {
    position: relative;
    height: 260px;
}
.archdio-sim-footer {
    text-align: center;
    color: #6b4a3a;
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding-top: 16px;
    border-top: 1px solid #c9a85b;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
}
.archdio-footer-mark { font-style: italic; }
@media (max-width: 768px) {
    .archdio-sim-container { padding: 16px; }
    .archdio-sim-header {
        flex-direction: column;
        text-align: center;
        padding: 20px;
        gap: 14px;
    }
    .archdio-sim-header-text h1 { font-size: 1.2rem; }
    .archdio-sim-kpi-value { font-size: 1.6rem; }
    .archdio-sim-charts { grid-template-columns: 1fr; }
    .archdio-sim-footer { flex-direction: column; }
}


/* --- EQIL 2026-08-08: accessibility + debrief --- */
.archdio-sim :is(select, button, a, input, [tabindex]):focus-visible,
select:focus-visible, button:focus-visible, input:focus-visible {
    outline: 3px solid #1d4ed8;
    outline-offset: 2px;
    border-radius: 4px;
}
.archdio-debrief {
    margin-top: 1.25rem;
    padding: 1rem 1.25rem;
    border: 1px solid #d9d2c4;
    border-radius: 8px;
    background: #fdfcf8;
}
.archdio-debrief-table {
    width: 100%;
    border-collapse: collapse;
    margin: 0.5rem 0 0.75rem;
}
.archdio-debrief-table th,
.archdio-debrief-table td {
    text-align: left;
    padding: 0.3rem 0.5rem;
    border-bottom: 1px solid #ece7dc;
    font-size: 0.92rem;
}
.archdio-debrief-insights li { margin-bottom: 0.35rem; }
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        transition-duration: 0.001ms !important;
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        scroll-behavior: auto !important;
    }
}

