        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const corpus = ds.corpusHistory || [];
            const align = ds.alignmentHistory || [];
            const labels = corpus.map((_, i) => 'R' + (i + 1));
            return {
                corpusChart: { labels: labels, datasets: [{ data: corpus, label: this._t('chart_corpus_label') }] },
                alignmentChart: { labels: labels, datasets: [{ data: align, label: this._t('chart_alignment_label') }] }
            };
