        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            const totalScore = history.reduce((s, r) => s + ((r.results && r.results.roundScore) || 0), 0);

            let performance = 'apprentice';
            if (totalScore >= 130) performance = 'master';
            else if (totalScore >= 95) performance = 'skilled';
            else if (totalScore >= 60) performance = 'developing';

            const insights = [];
            const last = history[history.length - 1];
            const res = (last && last.results) || {};
            if (last && last.results) {
                if (res.endowment >= 390) insights.push(this._t('insight_corpus_preserved'));
                else if (res.endowment < 320) insights.push(this._t('insight_corpus_eroded'));
                else insights.push(this._t('insight_corpus_neutral'));

                if (res.covenantStatus === 'resolved') insights.push(this._t('insight_cov_resolved'));
                else insights.push(this._t('insight_cov_breached'));

                if (res.avgAlignment >= 75) insights.push(this._t('insight_align_strong'));
                else if (res.avgAlignment < 50) insights.push(this._t('insight_align_fragile'));
                else insights.push(this._t('insight_align_mixed'));
            }

            return {
                totalScore: totalScore,
                overallScore: totalScore,
                score: totalScore,
                composite: totalScore,
                performance: performance,
                performanceKey: performance,
                performanceLabel: this._t('perf_' + performance),
                finalEndowment: res.endowment,
                finalAlignment: res.avgAlignment,
                covenantStatus: res.covenantStatus,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            if (!summary) return '';
            const s = summary;
            const covLabel = s.covenantStatus === 'resolved'
                ? this._t('cov_resolved_short', 'Resolved')
                : this._t('cov_breached_short', 'Breached');
            const rows = [
                [this._t('sum_score'), String(s.overallScore)],
                [this._t('sum_band'), s.performanceLabel],
                [this._t('col_endow'), '$' + s.finalEndowment + 'M'],
                [this._t('col_cov'), covLabel],
                [this._t('col_align'), s.finalAlignment + '%']
            ];
            let html = '<div class="archdio-debrief"><h3>' + this._t('sum_heading') + '</h3>';
            html += '<table class="archdio-debrief-table"><tbody>';
            rows.forEach(function (r) { html += '<tr><th scope="row">' + r[0] + '</th><td>' + r[1] + '</td></tr>'; });
            html += '</tbody></table><ul class="archdio-debrief-insights">';
            (s.insights || []).forEach(function (t) { html += '<li>' + t + '</li>'; });
            html += '</ul></div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            const period = state.currentPeriod;
            if (period === 1) {
                if (state.domainState.sustainableRateGap > 0.6) return window.mySimulation.t('hint_gap_wide');
            }
            if (period === 2) {
                if (!state.domainState.universityCovenantResolved) return window.mySimulation.t('hint_covenant');
                if (state.decisions.realEstateSale > 60) return window.mySimulation.t('hint_oversize_sale');
            }
            if (period === 3) {
                if (state.domainState.archbishopAlignment < 50) return window.mySimulation.t('hint_archbishop');
                if (state.domainState.pastorAlignment < 50) return window.mySimulation.t('hint_pastor');
                if (state.domainState.layChairAlignment < 50) return window.mySimulation.t('hint_laychair');
            }
            return null;
        }

