        _updateBriefing(state) {
            const period = this._isRunComplete(state) ? 4 : (state.currentPeriod || 1);
            const r1Panel = document.getElementById('round1Panel');
            const r2Panel = document.getElementById('round2Panel');
            const r3Panel = document.getElementById('round3Panel');
            const briefEl = document.getElementById('roundBriefing');

            if (r1Panel) r1Panel.style.display = (period === 1) ? 'block' : 'none';
            if (r2Panel) r2Panel.style.display = (period === 2) ? 'block' : 'none';
            if (r3Panel) r3Panel.style.display = (period === 3) ? 'block' : 'none';

            const actionRow = document.getElementById('usfActionRow');
            if (actionRow) actionRow.style.display = this._isRunComplete(state) ? 'none' : '';

            if (briefEl && window.mySimulation && window.mySimulation.t) {
                let key = 'r1_brief';
                if (period === 2) key = 'r2_brief';
                else if (period === 3) key = 'r3_brief';
                else if (period > 3) key = 'r_done';
                briefEl.innerHTML = window.mySimulation.t(key);
            }
        }

        _updateStakeholderBars(state) {
            const aBar = document.getElementById('archBar');
            const lBar = document.getElementById('layBar');
            const pBar = document.getElementById('pastorBar');
            if (aBar) aBar.style.width = (state.domainState.archbishopAlignment || 0) + '%';
            if (lBar) lBar.style.width = (state.domainState.layChairAlignment || 0) + '%';
            if (pBar) pBar.style.width = (state.domainState.pastorAlignment || 0) + '%';
